import{_ as t,o as a,c as r,a2 as o}from"./chunks/framework.DWOyCk6h.js";const m=JSON.parse('{"title":"Workflow Template RFC","description":"","frontmatter":{"title":"Workflow Template RFC"},"headers":[],"relativePath":"en/extend/workflow-template-rfc.md","filePath":"en/extend/workflow-template-rfc.md","lastUpdated":1785141211000}'),d={name:"en/extend/workflow-template-rfc.md"};function l(i,e,n,s,c,p){return a(),r("div",null,[...e[0]||(e[0]=[o('<h1 id="workflow-template-rfc" tabindex="-1">Workflow Template RFC <a class="header-anchor" href="#workflow-template-rfc" aria-label="Permalink to &quot;Workflow Template RFC&quot;">​</a></h1><h2 id="overview" tabindex="-1">Overview <a class="header-anchor" href="#overview" aria-label="Permalink to &quot;Overview&quot;">​</a></h2><p>Workflow templates allow users to quickly create pre-configured workflows for common scenarios. This RFC defines the template registration mechanism.</p><h2 id="template-structure" tabindex="-1">Template Structure <a class="header-anchor" href="#template-structure" aria-label="Permalink to &quot;Template Structure&quot;">​</a></h2><p>A workflow template consists of:</p><ul><li><strong>Metadata</strong>: ID, name, description, category, icon, tags</li><li><strong>Graph</strong>: Complete workflow graph (nodes, edges, entry node)</li><li><strong>Default Data</strong>: Default configuration for each node</li></ul><h2 id="registration" tabindex="-1">Registration <a class="header-anchor" href="#registration" aria-label="Permalink to &quot;Registration&quot;">​</a></h2><p>Templates are registered via the <code>AGENT_WORKFLOW_TEMPLATES</code> array in <code>shared/platform-shared/ai/agentWorkflow/templates.ts</code>. Each template has a factory function that generates the graph.</p><h2 id="categories" tabindex="-1">Categories <a class="header-anchor" href="#categories" aria-label="Permalink to &quot;Categories&quot;">​</a></h2><table tabindex="0"><thead><tr><th>Category</th><th>Description</th></tr></thead><tbody><tr><td>general</td><td>General-purpose workflows</td></tr><tr><td>document</td><td>Document processing</td></tr><tr><td>assistant</td><td>AI assistant</td></tr><tr><td>integration</td><td>External integrations</td></tr><tr><td>batch</td><td>Batch processing</td></tr><tr><td>customer-service</td><td>Customer service</td></tr><tr><td>audit</td><td>Compliance &amp; audit</td></tr><tr><td>hr</td><td>Human resources</td></tr><tr><td>finance</td><td>Finance</td></tr><tr><td>operations</td><td>Operations</td></tr></tbody></table><h2 id="adding-a-new-template" tabindex="-1">Adding a New Template <a class="header-anchor" href="#adding-a-new-template" aria-label="Permalink to &quot;Adding a New Template&quot;">​</a></h2><ol><li>Add template ID to <code>AgentWorkflowTemplateId</code> type</li><li>Add metadata to <code>AGENT_WORKFLOW_TEMPLATES</code> array</li><li>Create factory function <code>createXxxWorkflowGraph()</code></li><li>Register in <code>createAgentWorkflowGraphByTemplate()</code> switch</li></ol><h2 id="db-storage" tabindex="-1">DB Storage <a class="header-anchor" href="#db-storage" aria-label="Permalink to &quot;DB Storage&quot;">​</a></h2><p>Templates are also stored in MongoDB via <code>WorkflowTemplateModel</code>. Built-in templates are seeded on server startup. Users can create custom templates via the Template Manager UI.</p>',14)])])}const f=t(d,[["render",l]]);export{m as __pageData,f as default};
